class Widget {
public:
  void swap(Widget& other) noexcept { /* ... */ }
};

// Conditionally noexcept based on the swap operation for T
template<typename T, size_t N>
void swap_array(T (&a)[N], T (&b)[N]) noexcept(noexcept(swap(*a, *b))) {
  // ...
}

// swap_array for Widgets will be noexcept because Widget::swap is noexcept
Widget w1[10], w2[10];
swap_array(w1, w2); // This call is noexcept

// swap_array for a type with a throwing swap would not be noexcept
